package org.genhttp.modules.clientcaching.policy

import org.genhttp.api.content.Concern
import org.genhttp.api.content.ConcernBuilder
import org.genhttp.api.content.Handler
import org.genhttp.api.infrastructure.BuilderMissingPropertyException
import org.genhttp.api.protocol.Request
import org.genhttp.api.protocol.Response

import kotlin.time.Duration
import kotlin.time.Duration.Companion.days

/**
 * Builds a concern that instructs the client how long it may cache the content generated by the server.
 */
public class CachePolicyBuilder : ConcernBuilder {

    private var duration: Duration? = null

    private var predicate: ((Request, Response) -> Boolean)? = null

    // region Functionality

    /**
     * Instructs the client to cache the content generated by the server for the given duration.
     *
     * @param duration The duration the content should be cached on the client
     */
    public fun duration(duration: Duration): CachePolicyBuilder {
        this.duration = duration
        return this
    }

    /**
     * Instructs the client to cache the content generated by the server for the given number of days.
     *
     * @param days The number of days the content should be cached on the client
     */
    public fun duration(days: Int): CachePolicyBuilder = duration(days.days)

    /**
     * Allows to filter the responses which should be cached by the client.
     *
     * @param predicate The predicate to be evaluated to check, whether content should be cached
     */
    public fun predicate(predicate: (Request, Response) -> Boolean): CachePolicyBuilder {
        this.predicate = predicate
        return this
    }

    override fun build(content: Handler): Concern {
        val duration = duration ?: throw BuilderMissingPropertyException("Duration")

        return CachePolicyConcern(content, duration, predicate)
    }

    // endregion

}
